//! hydo-history against the frozen answers of hydo/history/hydohist.py (the Python reference,
//! deleted in M107; `git show 2a58c4b:hydo/history/hydohist.py`). The cases are made here, by the
//! exact ports of the old generators (tests/gen/), and their answers are compared with what
//! hydohist.py answered for the same cases, recorded in tests/golden/:
//!
//! - `units.txt`: every history the 46 tests of test_hydohist.py checked (119 cases, each with
//!   its test's name): the hand-written ones verbatim, the Randomized ones regenerated by the
//!   port of its `gen_linearizable` (their case text is pinned by its SHA-256), every answer
//!   verbatim;
//! - `corpus.txt`: tests/equiv.py's seeded random corpus (seeds 1, 2, 3, 105 and 2026: 58,000
//!   cases and 3,480 percent-coding and console-decoding cases) and the long histories (60 with
//!   `--large`, 40 with `--witness`), as chunked SHA-256 of the case lines (`gen:`) and of the
//!   answer lines (`ans:`), 256 lines a chunk.
//!
//! By default the test checks the units and the first 2 chunks of every seed (about 2,500 cases);
//! with `HYDO_HIST_FULL=1` every chunk and the long histories (the whole corpus: about 25 s with
//! `--release`, several minutes without). With
//! `HYDO_BLESS=1` it rewrites the goldens from the Rust answers (the Rust crate is the reference
//! from M107 on; bless only a deliberate change and say so in the commit).

mod gen;

use sha2::{Digest, Sha256};
use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::path::PathBuf;

const CHUNK: usize = 256;
const QUICK_CHUNKS: usize = 2;

fn golden(name: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/golden")
        .join(name)
}

fn bless() -> bool {
    std::env::var_os("HYDO_BLESS").is_some()
}

fn full() -> bool {
    std::env::var_os("HYDO_HIST_FULL").is_some()
}

fn sha(lines: &[String]) -> String {
    let mut h = Sha256::new();
    for l in lines {
        h.update(l.as_bytes());
        h.update(b"\n");
    }
    h.finalize().iter().map(|b| format!("{b:02x}")).collect()
}

fn header(path: &str) -> String {
    std::fs::read_to_string(golden(path))
        .unwrap_or_default()
        .lines()
        .take_while(|l| l.starts_with('#'))
        .map(|l| format!("{l}\n"))
        .collect()
}

/// The comment lines and the data lines of a golden file.
fn data(path: &str) -> Vec<String> {
    std::fs::read_to_string(golden(path))
        .unwrap_or_else(|e| panic!("tests/golden/{path}: {e}"))
        .lines()
        .filter(|l| !l.starts_with('#') && !l.is_empty())
        .map(String::from)
        .collect()
}

// ------------------------------------------------------------------ the unit tests' histories
#[test]
fn unit_test_histories_answer_as_recorded() {
    let rows = data("units.txt");
    let mut randomized = gen::randomized_units().into_iter();
    let mut out = header("units.txt");
    let mut bad = Vec::new();
    let mut by_test: BTreeMap<String, usize> = BTreeMap::new();
    for (i, row) in rows.iter().enumerate() {
        let f: Vec<&str> = row.splitn(3, '\t').collect();
        assert_eq!(f.len(), 3, "units.txt line {i}: name, case, answer");
        let (name, case_field, want) = (f[0], f[1], f[2]);
        let case = if let Some(h) = case_field.strip_prefix("sha256:") {
            let (gname, c) = randomized.next().expect("a Randomized case");
            assert_eq!(
                gname, name,
                "units.txt line {i}: the Randomized tests' order"
            );
            let got = sha(std::slice::from_ref(&c))[..].to_string();
            assert_eq!(
                got, h,
                "{name}: the regenerated case differs from the recorded one"
            );
            c
        } else {
            case_field.to_string()
        };
        let (got, _) = hydo_history::equiv::answer(&case);
        if got != want {
            bad.push(format!(
                "{name} (line {i}):\n  case: {case}\n  want: {want}\n  got:  {got}"
            ));
        }
        if name.starts_with("test_") {
            *by_test.entry(name.to_string()).or_default() += 1;
        }
        let _ = writeln!(out, "{name}\t{case_field}\t{got}");
    }
    assert!(
        randomized.next().is_none(),
        "more Randomized cases than recorded"
    );
    if bless() {
        std::fs::write(golden("units.txt"), out).unwrap();
        return;
    }
    assert!(
        bad.is_empty(),
        "{} of {} differ:\n{}",
        bad.len(),
        rows.len(),
        bad.join("\n")
    );
    assert_eq!(rows.len(), 119);
    eprintln!(
        "units: {} cases ({} tests of test_hydohist.py, and equiv.py's percent-coding cases) identical to the recorded answers",
        rows.len(),
        by_test.len()
    );
}

// ------------------------------------------------------------------ the seeded corpus
/// The corpus labels: (label, cases, seed, large, witness).
const CORPUS: [(&str, usize, u64, bool, bool); 7] = [
    ("seed1", 2000, 1, false, false),
    ("seed2", 3000, 2, false, false),
    ("seed3", 3000, 3, false, false),
    ("seed105", 25000, 105, false, false),
    ("seed2026", 25000, 2026, false, false),
    ("large1", 60, 1, true, false),
    ("witness1", 40, 1, false, true),
];

fn chunks(lines: &[String]) -> Vec<(usize, String)> {
    lines.chunks(CHUNK).map(|c| (c.len(), sha(c))).collect()
}

#[test]
fn seeded_corpus_answers_as_recorded() {
    let rows = data("corpus.txt");
    let mut want: BTreeMap<(String, usize), (usize, String)> = BTreeMap::new();
    for r in &rows {
        let f: Vec<&str> = r.split('\t').collect();
        assert_eq!(f.len(), 4, "corpus.txt: label, chunk, count, sha256: {r}");
        want.insert(
            (f[0].to_string(), f[1].parse().unwrap()),
            (f[2].parse().unwrap(), f[3].to_string()),
        );
    }
    let all = full() || bless();
    let mut out = header("corpus.txt");
    let (mut ncases, mut nchunks, mut bad) = (0usize, 0usize, Vec::new());
    for (label, n, seed, large, witness) in CORPUS {
        if !all && (large || witness) {
            continue; // the long histories only with HYDO_HIST_FULL=1
        }
        let limit = if all {
            usize::MAX
        } else {
            QUICK_CHUNKS * CHUNK
        };
        let cases = gen::gen(n, seed, large, witness, limit);
        let answers: Vec<String> = cases
            .iter()
            .map(|c| hydo_history::equiv::answer(c).0)
            .collect();
        ncases += cases.len();
        for (kind, lines) in [("gen", &cases), ("ans", &answers)] {
            let key = format!("{kind}:{label}");
            for (ci, (cnt, h)) in chunks(lines).into_iter().enumerate() {
                let _ = writeln!(out, "{key}\t{ci}\t{cnt}\t{h}");
                nchunks += 1;
                match want.get(&(key.clone(), ci)) {
                    Some((wc, wh)) if *wc == cnt && *wh == h => {}
                    other => {
                        let first = &lines[ci * CHUNK..ci * CHUNK + cnt];
                        bad.push(format!(
                            "{key} chunk {ci} ({cnt} lines, {h}) differs from the recorded {other:?}; \
                             its first Rust lines:\n  {}",
                            first.iter().take(3).map(|l| l.chars().take(400).collect::<String>())
                                .collect::<Vec<_>>().join("\n  ")
                        ));
                    }
                }
            }
        }
    }
    if bless() {
        std::fs::write(golden("corpus.txt"), out).unwrap();
        return;
    }
    if all {
        assert_eq!(nchunks, want.len(), "the recorded corpus has other chunks");
    }
    assert!(
        bad.is_empty(),
        "{} of {nchunks} chunks differ:\n{}",
        bad.len(),
        bad.join("\n")
    );
    eprintln!(
        "corpus: {ncases} cases ({nchunks} chunks of cases and answers) identical to hydohist.py's \
         recorded answers{}",
        if all { " (the whole corpus)" } else { " (HYDO_HIST_FULL=1 for all of it)" }
    );
}

/// Writes the generated cases for the recording (`HYDO_HIST_DUMP=<dir> cargo test -- --ignored`):
/// `<label>.jsonl` and `units.jsonl` (the Randomized cases).
#[test]
#[ignore]
fn dump_cases() {
    let dir = PathBuf::from(std::env::var("HYDO_HIST_DUMP").expect("HYDO_HIST_DUMP"));
    for (label, n, seed, large, witness) in CORPUS {
        let mut s = gen::gen(n, seed, large, witness, usize::MAX).join("\n");
        s.push('\n');
        std::fs::write(dir.join(format!("{label}.jsonl")), s).unwrap();
    }
    let mut s = String::new();
    for (name, c) in gen::randomized_units() {
        let _ = writeln!(s, "{name}\t{c}");
    }
    std::fs::write(dir.join("randomized.tsv"), s).unwrap();
}
